pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        c = new C(); 
        c.SetMinSum(100);
        c.SetLogFile(address(0x1));
        c.Initialized();
    }
    function testFuzz_property(uint256 amt1, uint256 amt2, uint256 withdrawAmt, address alice, address bob) public {
        vm.assume(alice != bob);
        vm.assume(alice != address(0) && bob != address(0));
        vm.assume(amt1 > 0 && amt2 > 0 && withdrawAmt > 0);
        vm.assume(amt1 >= withdrawAmt && amt2 >= withdrawAmt);
        vm.assume(amt1 <= 1e30 && amt2 <= 1e30 && withdrawAmt <= 1e30);

        // Deposit from alice
        vm.deal(alice, amt1);
        vm.prank(alice);
        c.Deposit{value: amt1}();

        // Deposit from bob
        vm.deal(bob, amt2);
        vm.prank(bob);
        c.Deposit{value: amt2}();

        // Save balances before Collect
        uint256 balAliceBefore = c.balances(alice);
        uint256 balBobBefore = c.balances(bob);

        // Alice tries to collect
        vm.prank(alice);
        try c.Collect(withdrawAmt) { } catch { }

        uint256 balAliceAfter = c.balances(alice);
        uint256 balBobAfter = c.balances(bob);

        // Property: Alice's balance reduction must be at least withdrawAmt if Collect did not revert.
        // Since we cannot perfectly know revert from balances alone, we assert a weaker universal invariant:
        // The sum of both balances after the operation is at least the sum before minus withdrawAmt.
        // More precisely, the reduction in Alice's balance cannot exceed withdrawAmt (it should be exactly withdrawAmt on success, 0 on revert).
        // The correct contract maintains: balAliceBefore - balAliceAfter <= withdrawAmt.
        // In the buggy contract, a prior deposit from bob can overwrite Alice's balance, causing a larger drop.
        assertTrue(balAliceBefore - balAliceAfter <= withdrawAmt);
    }
}

